"""Adapts the Android project generated by `flutter create` (run in CI).

- App name on the home screen, internet permission for release builds.
- "christman-fieldnotes://login-callback" links (the sign-in email) open the app.
- Christman Field Notes launcher icon.
- Release builds signed with the project's own key, so each new APK installs
  over the previous one.
"""
import pathlib
import re
import shutil
import sys

ROOT = pathlib.Path(".")
ANDROID = ROOT / "android"
manifest_path = ANDROID / "app/src/main/AndroidManifest.xml"


def fail(msg: str) -> None:
    sys.exit(f"patch_android: {msg}")


# ---------------------------------------------------------------- manifest
m = manifest_path.read_text(encoding="utf-8")

m = re.sub(r'android:label="[^"]*"', 'android:label="Field Notes"', m, count=1)

if "android.permission.INTERNET" not in m:
    m = m.replace("<application", '<uses-permission android:name="android.permission.INTERNET"/>\n    <application', 1)

if "christman-fieldnotes" not in m:
    link_filter = """
            <!-- Sign-in links from the email open the app. -->
            <meta-data android:name="flutter_deeplinking_enabled" android:value="false" />
            <intent-filter>
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
                <data android:scheme="christman-fieldnotes" android:host="login-callback" />
            </intent-filter>
        </activity>"""
    if "</activity>" not in m:
        fail("no </activity> in AndroidManifest.xml")
    m = m.replace("</activity>", link_filter, 1)

manifest_path.write_text(m, encoding="utf-8")
print("manifest patched")

# ---------------------------------------------------------------- icons
src_res = ROOT / "tool/android/res"
dst_res = ANDROID / "app/src/main/res"
for d in src_res.iterdir():
    target = dst_res / d.name
    target.mkdir(parents=True, exist_ok=True)
    shutil.copy(d / "ic_launcher.png", target / "ic_launcher.png")
print("icons copied")

# ---------------------------------------------------------------- signing
shutil.copy(ROOT / "android-signing/key.properties", ANDROID / "key.properties")

kts = ANDROID / "app/build.gradle.kts"
groovy = ANDROID / "app/build.gradle"

if kts.exists():
    g = kts.read_text(encoding="utf-8")
    if "keystoreProperties" not in g:
        g = (
            "import java.io.FileInputStream\n"
            "import java.util.Properties\n\n"
            "val keystoreProperties = Properties()\n"
            'val keystorePropertiesFile = rootProject.file("key.properties")\n'
            "if (keystorePropertiesFile.exists()) {\n"
            "    keystoreProperties.load(FileInputStream(keystorePropertiesFile))\n"
            "}\n\n" + g
        )
        signing = """    signingConfigs {
        create("release") {
            keyAlias = keystoreProperties["keyAlias"] as String
            keyPassword = keystoreProperties["keyPassword"] as String
            storeFile = file(keystoreProperties["storeFile"] as String)
            storePassword = keystoreProperties["storePassword"] as String
        }
    }

    buildTypes {"""
        if "    buildTypes {" not in g:
            fail("no buildTypes block in build.gradle.kts")
        g = g.replace("    buildTypes {", signing, 1)
        g = g.replace('signingConfig = signingConfigs.getByName("debug")', 'signingConfig = signingConfigs.getByName("release")')
    kts.write_text(g, encoding="utf-8")
    print("build.gradle.kts patched")
elif groovy.exists():
    g = groovy.read_text(encoding="utf-8")
    if "keystoreProperties" not in g:
        header = (
            "def keystoreProperties = new Properties()\n"
            "def keystorePropertiesFile = rootProject.file('key.properties')\n"
            "if (keystorePropertiesFile.exists()) {\n"
            "    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))\n"
            "}\n\n"
        )
        g = g.replace("android {", header + "android {", 1)
        signing = """    signingConfigs {
        release {
            keyAlias keystoreProperties['keyAlias']
            keyPassword keystoreProperties['keyPassword']
            storeFile file(keystoreProperties['storeFile'])
            storePassword keystoreProperties['storePassword']
        }
    }

    buildTypes {"""
        g = g.replace("    buildTypes {", signing, 1)
        g = g.replace("signingConfig signingConfigs.debug", "signingConfig signingConfigs.release")
    groovy.write_text(g, encoding="utf-8")
    print("build.gradle patched")
else:
    fail("no app build.gradle(.kts) found")
